import{_ as a,o as n,c as s,a3 as t}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"压缩包目录结构","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"压缩包目录结构 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/reference/layout"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/layout"}]]},"headers":[],"relativePath":"zh/xclang/reference/layout.md","filePath":"zh/xclang/reference/layout.md","lastUpdated":1794509097000}'),c={name:"zh/xclang/reference/layout.md"};function d(o,e,l,i,r,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="压缩包目录结构" tabindex="-1">压缩包目录结构 <a class="header-anchor" href="#压缩包目录结构" aria-label="Permalink to &quot;压缩包目录结构&quot;">​</a></h1><p>本页列出解压后的工具链压缩包内容，即文档中记作 <code>$XCLANG</code> 的工具链目录。每个主机压缩包都内置了全部目标平台的 sysroot；不同主机压缩包之间的差异仅在于 <code>bin/</code>（其中的可执行程序，以及随主机而异的 macOS 与 MSVC 目标平台配置文件）和这些可执行程序所链接组件的许可证声明。为何采用这种目录布局见<a href="./../design/toolchain">工具链结构</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xclang/</span></span>
<span class="line"><span>  bin/                     llvm and its names (clang, clang++, clang-cl,</span></span>
<span class="line"><span>                           clang-scan-deps, ld.lld, ld64.lld, lld-link,</span></span>
<span class="line"><span>                           llvm-ar, llvm-objcopy, windres, dsymutil,</span></span>
<span class="line"><span>                           llvm-gsymutil, ...), the tools outside it</span></span>
<span class="line"><span>                           (llvm-profdata, llvm-cov, llvm-dwarfdump,</span></span>
<span class="line"><span>                           llvm-strings, FileCheck), the xclang command,</span></span>
<span class="line"><span>                           and &lt;target&gt;.cfg for every spelling of every</span></span>
<span class="line"><span>                           target, with &lt;target&gt;-system.cfg beside it for</span></span>
<span class="line"><span>                           the platform&#39;s C++ library (-stdlib=platform),</span></span>
<span class="line"><span>                           and their clang-cl files, &lt;target&gt;-clang-cl.cfg</span></span>
<span class="line"><span>                           and &lt;target&gt;-clang-cl-system.cfg;</span></span>
<span class="line"><span>                           &lt;target&gt;-sdk.cfg and &lt;target&gt;-clang-cl-sdk.cfg,</span></span>
<span class="line"><span>                           the SDK in use of an MSVC target, which the</span></span>
<span class="line"><span>                           xclang command writes; on x64 Windows hosts,</span></span>
<span class="line"><span>                           copies of the x64 MinGW and MSVC targets&#39; ASan</span></span>
<span class="line"><span>                           DLLs (Windows: ASan&#39;s DLL)</span></span>
<span class="line"><span>  lib/clang/&lt;major&gt;/       clang&#39;s resource headers, compiler-rt&#39;s headers,</span></span>
<span class="line"><span>                           and compiler-rt for every target; for the MSVC</span></span>
<span class="line"><span>                           targets libc++ too</span></span>
<span class="line"><span>  lib/cmake/xclang/        the CMake package</span></span>
<span class="line"><span>  libc++/include/c++/v1/   libc++&#39;s headers, the same for every target</span></span>
<span class="line"><span>  libc++/include/&lt;target&gt;/c++/v1/</span></span>
<span class="line"><span>                           each target&#39;s own __config_site, &lt;target&gt; as</span></span>
<span class="line"><span>                           clang spells it (x86_64-w64-windows-gnu)</span></span>
<span class="line"><span>  libc++/src/              the runtimes&#39; sources, the same for every target,</span></span>
<span class="line"><span>                           in llvm-project&#39;s layout, patched (below)</span></span>
<span class="line"><span>  mingw-w64/include/       mingw-w64&#39;s headers, the same for both Windows</span></span>
<span class="line"><span>                           targets</span></span>
<span class="line"><span>  share/licenses/          the license notices of everything in the archive</span></span>
<span class="line"><span>                           (below)</span></span>
<span class="line"><span>  &lt;target&gt;/                the sysroot of each target (below)</span></span>
<span class="line"><span>  sdk/                     not in the archive: the vendor SDKs that the</span></span>
<span class="line"><span>                           xclang command fetches, and sdk/windows,</span></span>
<span class="line"><span>                           sdk/macos, those in use</span></span>
<span class="line"><span>  LICENSE                  xclang&#39;s license</span></span></code></pre></div><p>MSVC 目标平台没有内置 sysroot，其 C 标准库来自下载的 SDK。它们的 compiler-rt 与 libc++ 存放在 lld-link 会自动搜索的 <code>lib/clang/&lt;major&gt;/lib/windows</code> 目录下，包括 <code>libc++-&lt;arch&gt;.lib</code>、<code>libc++experimental-&lt;arch&gt;.lib</code> 以及面向 x64 的 <code>libc++asan-x86_64.lib</code>；目标平台的 <code>__config_site</code> 会在每个包含 libc++ 头文件的目标文件中声明引用对应库文件（<a href="./../design/windows#libc-on-vcruntime">Windows</a>）。它们的 <code>&lt;target&gt;/</code> 目录下存放了 libc++ 的模块源码（<code>share/libc++/v1</code>）、<code>-print-library-module-manifest-path</code> 在 MSVC 目标平台上不会报告的模块清单（<code>lib/libc++.modules.json</code>），以及 ASan 构建版本的 <code>__config_site</code>（<code>lib/asan/include</code>）。</p><h2 id="sysroot" tabindex="-1">Sysroot <a class="header-anchor" href="#sysroot" aria-label="Permalink to &quot;Sysroot&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Linux</th><th>Linux（musl）</th><th>Windows（MinGW）</th><th>macOS</th></tr></thead><tbody><tr><td>C 标准库</td><td>glibc 2.17：头文件位于 <code>usr/include</code>，启动文件与库文件位于 <code>lib64</code> 和 <code>usr/lib64</code></td><td>musl 1.2.6：头文件位于 <code>usr/include</code>，启动文件、<code>libc.a</code> 以及空的 <code>libm.a</code>、<code>libpthread.a</code> 等位于 <code>usr/lib</code></td><td>mingw-w64（UCRT）与 winpthreads：库文件位于 <code>lib</code>，头文件位于共用的 <code>mingw-w64/include</code></td><td>无内置库：使用 Apple 的 SDK，取自本机 Xcode 或 Linux 与 Windows 主机上的 <code>sdk/macos</code>（<a href="./../guide/cross-compiling#on-linux-and-windows-hosts">macOS</a>）</td></tr><tr><td>内核头文件</td><td>Linux 3.10（x64）、4.18（arm64），位于 <code>usr/include</code></td><td>Linux 6.18，位于 <code>usr/include</code></td><td></td><td></td></tr><tr><td>libc++、libc++abi、libunwind</td><td><code>usr/lib</code>；头文件位于共用的 <code>libc++/include/c++/v1</code></td><td><code>usr/lib</code>；头文件同左</td><td><code>lib</code>；头文件同左</td><td><code>lib</code>（不含 libunwind，使用系统 libSystem 中的实现）；头文件同左</td></tr><tr><td>libc++ 模块源码</td><td><code>usr/share/libc++/v1</code></td><td><code>usr/share/libc++/v1</code></td><td><code>share/libc++/v1</code></td><td><code>share/libc++/v1</code></td></tr><tr><td>libc++ 模块清单</td><td><code>usr/lib/libc++.modules.json</code></td><td><code>usr/lib/libc++.modules.json</code></td><td><code>lib/libc++.modules.json</code></td><td><code>lib/libc++.modules.json</code></td></tr><tr><td>ASan libc++</td><td><code>usr/lib/asan</code></td><td>无</td><td>x64：<code>lib/asan</code></td><td><code>lib/asan</code></td></tr><tr><td>GCC 库名兼容</td><td>空的 <code>libatomic.a</code>、<code>libgcc.a</code>、<code>libgcc_eh.a</code>、<code>libgcc_s.a</code></td><td>同左</td><td>同左，外加 <code>libssp.a</code>、<code>libssp_nonshared.a</code></td><td>无</td></tr></tbody></table><p>运行 <code>clang++ --target=&lt;target&gt; -print-library-module-manifest-path</code> 可输出模块清单的路径。</p><h2 id="共用头文件" tabindex="-1">共用头文件 <a class="header-anchor" href="#共用头文件" aria-label="Permalink to &quot;共用头文件&quot;">​</a></h2><p>多个目标平台共用的头文件在压缩包中只存放一份，且不使用符号链接。libc++ 的头文件在不同目标平台之间只有各自独立的 <code>__config_site</code> 不同，因此 <code>libc++/include</code> 采用 LLVM 按目标平台区分的运行时布局：共用头文件放在 <code>c++/v1</code> 下，各目标平台的专属文件放在 <code>&lt;target&gt;/c++/v1</code> 下。mingw-w64 的头文件在 x64 与 arm64 之间完全相同，统一存放在 <code>mingw-w64/include</code> 下。各配置文件会依次指定这些目录：先通过 <code>-stdlib++-isystem</code> 引入目标平台的 <code>__config_site</code>，再引入共用的 libc++ 头文件；Windows 目标平台还会传入 <code>-idirafter mingw-w64/include</code>，使其与普通 sysroot 的 <code>include</code> 目录一样排在 clang 内置头文件之后。使用 <code>--no-default-config</code> 并自行指定 <code>--sysroot</code> 的构建也需要显式传入这些目录。</p><p>这些头文件没有放在顶层的 <code>include/</code> 下：clang 驱动会自动在 <code>&lt;toolchain&gt;/include/c++/v1</code> 中查找 libc++（在 macOS 上甚至优先于 SDK），如果放在那里，传入 <code>--no-default-config</code> 时就会找到缺少 <code>__config_site</code> 的 xclang 头文件，而非系统的头文件。</p><h2 id="运行时库源码" tabindex="-1">运行时库源码 <a class="header-anchor" href="#运行时库源码" aria-label="Permalink to &quot;运行时库源码&quot;">​</a></h2><p><code>libc++/src</code> 存放了构建各目标平台运行时库所需的单份源码：包含 llvm-project 的 <code>runtimes/</code>、<code>cmake/</code>、<code>llvm/cmake/</code>、<code>libcxx/</code>、<code>libcxxabi/</code>、<code>libunwind/</code> 与 <code>compiler-rt/</code>（剔除了测试与文档），以及 libc++ 所引用的 LLVM libc 内部头文件，并已打上 xclang 的相关补丁。CMake 包与 Bazel 模块会直接像在源码检出目录中一样，基于其中的 LLVM <code>runtimes/</code> 构建运行时库（<a href="./../features/runtimes-from-source">从源码构建运行时库</a>）。这部分源码解压后为 35 MB。</p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>工具链、libclang、ASan 版 libclang 以及选项表的每个压缩包中都包含 <code>share/licenses</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>share/licenses/</span></span>
<span class="line"><span>  README.md                each component: what of the archive it is, its</span></span>
<span class="line"><span>                           version, its license (an SPDX expression) and</span></span>
<span class="line"><span>                           where its source is</span></span>
<span class="line"><span>  sbom.spdx.json           the same as an SPDX 2.3 document</span></span>
<span class="line"><span>  &lt;component&gt;/             the component&#39;s license and notice files</span></span></code></pre></div><p>工具链包含的组件：</p><table tabindex="0"><thead><tr><th>目录</th><th>内容</th><th>许可证</th></tr></thead><tbody><tr><td><code>xclang</code></td><td>xclang 的配置文件、CMake 包与 <code>xclang</code> 命令</td><td>Apache-2.0</td></tr><tr><td><code>llvm-project</code></td><td>clang、lld、LLVM 工具、libc++、libc++abi、libunwind 与 compiler-rt；各文件保留其在 LLVM 源码树中的相对路径，<code>&lt;file&gt;.license</code> 则是从对应文件头部注释中提取出的版权声明</td><td>Apache-2.0 WITH LLVM-exception，以及第三方组件各自的许可证（正则表达式引擎、BLAKE3、xxHash、Unicode 转换与数据、Visual Studio Setup API 声明）</td></tr><tr><td><code>zlib</code>, <code>zstd</code></td><td>静态链接进可执行程序（macOS 主机仅链接 zstd）</td><td>Zlib；BSD-3-Clause OR GPL-2.0-only</td></tr><tr><td><code>glibc</code></td><td>Linux 目标平台的 C 标准库（2.17）</td><td>LGPL-2.1-or-later</td></tr><tr><td><code>musl</code></td><td>musl 目标平台的 C 标准库（1.2.6）</td><td>MIT，以及其 <code>COPYRIGHT</code> 中列出的部分：BSD-2-Clause、BSD-3-Clause、ISC、SunPro</td></tr><tr><td><code>linux</code></td><td>Linux 目标平台（glibc 与 musl）的内核 UAPI 头文件</td><td>GPL-2.0-only WITH Linux-syscall-note</td></tr><tr><td><code>nss</code></td><td>Linux 目标平台的 <code>libfreebl3.so</code>（由 glibc 的 <code>libcrypt</code> 加载）</td><td>MPL-2.0</td></tr><tr><td><code>mingw-w64</code></td><td>Windows 目标平台的头文件、CRT 与 winpthreads（Windows 主机的可执行程序同样链接了它们）</td><td>ZPL-2.1 及运行时其余部分的许可证</td></tr><tr><td><code>rust</code>, <code>rust-crates/&lt;crate&gt;-&lt;version&gt;</code></td><td>Rust 标准库以及 <code>bin/xclang</code> 所链接的各个 crate</td><td>各自对应的许可证</td></tr></tbody></table><p>glibc、glibc 目标平台的内核头文件与 NSS 取自 conda-forge 的 sysroot 软件包所重打包的 CentOS 7 组件：README 中列出了这些软件包、CentOS 源码 RPM 包以及对应的上游版本。musl 与 musl 目标平台的内核头文件则直接基于 musl 官方版本与 kernel.org 源码构建。libclang 压缩包包含 <code>xclang</code>、<code>llvm-project</code>、<code>zlib</code> 与 <code>zstd</code>（macOS 主机使用系统自带的库而不含 <code>zlib</code>，Windows 主机则额外包含 <code>mingw-w64</code>），选项表压缩包包含 <code>xclang</code> 与 <code>llvm-project</code>。</p><h2 id="不含符号链接" tabindex="-1">不含符号链接 <a class="header-anchor" href="#不含符号链接" aria-label="Permalink to &quot;不含符号链接&quot;">​</a></h2><p>在 Linux 与 macOS 主机上，<code>bin/</code> 下的各个工具名是指向 <code>llvm</code> 的符号链接。Windows 压缩包则不包含任何符号链接，因此无需额外权限即可解压，也能直接打包为 conda 软件包；其中的每个工具名都是一个轻量的<a href="./../design/windows#the-launchers">启动器</a>。Linux sysroot 同样不含符号链接：soname 链接直接存为普通文件，<code>libfoo.so</code> 链接则替换为链接器脚本（<a href="./../design/hermeticity#why-glibc-2-17">为什么选择 glibc 2.17</a>）。</p>`,20)])])}const b=a(c,[["render",d]]);export{g as __pageData,b as default};
